// Turn whatever this platform sends into the standard lead.
//
// Every source has its own field names - one calls it `full_name`, another
// `name`, a third splits it in two. Mapping them here is the whole job of a
// source workflow: everything downstream sees one shape.

function pick(source, ...names) {
  for (const name of names) {
    const value = source[name];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
}

return $input.all().map((item) => {
  const body = item.json.body || {};

  // Some platforms send one name field, some send two.
  const fullName = pick(body, 'full_name', 'fullName', 'name');
  const [firstFromFull, ...restOfFull] = fullName.split(/\s+/);

  const sizeText = pick(body, 'office_size_sqft', 'square_feet', 'sqft', 'size');

  const lead = {
    // Generated HERE, not in the pipeline, so the 202 reply can carry it.
    // The sender can then quote it when asking "what happened to my lead?".
    lead_id: `lead_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
    received_at: new Date().toISOString(),
    source: 'webhook',
    // Which platform posted it. Useful in the weekly summary: "Facebook 12,
    // Google 3" tells the owner where to spend next month.
    source_detail: pick(body, 'source', 'platform', 'campaign') || 'unknown',
    first_name: pick(body, 'first_name', 'firstName') || firstFromFull || '',
    last_name: pick(body, 'last_name', 'lastName') || restOfFull.join(' '),
    email: pick(body, 'email', 'email_address', 'e-mail').toLowerCase(),
    phone: pick(body, 'phone', 'phone_number', 'telephone'),
    company: pick(body, 'company', 'company_name', 'organisation', 'organization'),
    website: pick(body, 'website', 'company_website', 'url'),
    office_size_sqft: Number(String(sizeText).replace(/[^0-9.]/g, '')) || null,
    cleaning_frequency: pick(body, 'cleaning_frequency', 'frequency', 'how_often'),
    city: pick(body, 'city', 'town', 'location'),
    message: pick(body, 'message', 'comments', 'notes', 'enquiry', 'inquiry'),
    raw: body,
  };

  // A payload with neither an email nor anything to read is not a lead: it is
  // a misconfigured integration, and the sender deserves a 400 rather than a
  // cheerful 202 that hides the problem.
  const usable = Boolean(lead.email || lead.phone || lead.message);

  return { json: { usable, lead } };
});
